import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    MOD = 10**9 + 7

    try:
        t_str = next(iterator)
    except StopIteration:
        return

    t = int(t_str)

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = [int(next(iterator)) for _ in range(n)]

        pos = [0] * n
        for i, x in enumerate(a):
            pos[x] = i

        parent = list(range(n + 1))

        def find(i):
            path = []
            root = i
            while parent[root] != root:
                path.append(root)
                root = parent[root]
            for node in path:
                parent[node] = root
            return root

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                if root_i < root_j:
                    parent[root_j] = root_i
                else:
                    parent[root_i] = root_j
                return True
            return False

        for x in range(n):
            p_x = pos[x]
            p_x_plus_1 = pos[x + 1] if x + 1 < n else -1

            if p_x_plus_1 != -1:
                union(p_x, p_x_plus_1)

        components = {}
        for i in range(n):
            root = find(i)
            if root not in components:
                components[root] = 0
            components[root] += 1

        ans = 1
        for count in components.values():
            if count > 1:
                ans = (ans * count) % MOD

        results.append(str(ans))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
